        self.advance_frequency_timers(chunk);
        cycles -= chunk;
        self.frame_countdown -= chunk;
        if self.frame_countdown == 0 {
            self.frame_countdown = FRAME_SEQUENCER_PERIOD;
            self.tick_frame_sequencer();
        }
    }
