/// 512 Hz frame sequencer: length at 256 Hz, sweep at 128 Hz, envelope at 64 Hz.
fn tick_frame_sequencer(&mut self) {
    let step = self.frame_step;
    self.frame_step = (step + 1) % 8;
    if step % 2 == 0 {
        self.tick_lengths();
