        self.tone_channels[0].tick_sweep(sweep_control);
    }
    if step == 7 {
        let tone1_envelope = self.register(SOUND1CNT_H);
        let tone2_envelope = self.register(SOUND2CNT_L);
        let noise_envelope = self.register(SOUND4CNT_L);
